<?php
require_once dirname(__DIR__) . '/config/app.php';
function start_page(string $title, string $active = ''): void {
    $user = current_user(); $isAdmin = $user && $user['role'] === 'admin';
    $nav = $isAdmin ? [['Overview','admin/dashboard.php','dashboard'],['Students','admin/students.php','students'],['Courses','admin/courses.php','courses'],['Payments','admin/payments.php','payments']] : [['Overview','student/dashboard.php','dashboard'],['Browse courses','courses.php','courses'],['My learning','student/learning.php','learning'],['Payments','student/payments.php','payments']];
    $flash = $_SESSION['flash'] ?? null; unset($_SESSION['flash']);
    ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= e($title) ?> | Warwa International School</title><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="<?= e(app_url('assets/css/style.css')) ?>"></head><body class="min-h-screen bg-mist text-ink">
    <header class="site-header"><div class="mx-auto flex max-w-7xl items-center justify-between px-5 py-4"><a class="brand" href="<?= e(app_url($user ? ($isAdmin ? 'admin/dashboard.php' : 'student/dashboard.php') : 'index.php')) ?>"><span class="brand-mark">W</span><span><b>WARWA</b><small>INTERNATIONAL SCHOOL</small></span></a><div class="flex items-center gap-4"><span class="hidden text-sm text-slate-200 sm:block"><?= e($user['full_name'] ?? '') ?></span><?php if ($user): ?><form method="post" action="<?= e(app_url('logout.php')) ?>"><?= csrf_field() ?><button class="quiet-button">Sign out</button></form><?php else: ?><a class="quiet-button" href="<?= e(app_url('login.php')) ?>">Sign in</a><?php endif ?></div></div></header>
    <?php if ($user): ?><div class="mx-auto grid max-w-7xl gap-6 px-4 py-6 md:grid-cols-[220px_1fr] lg:px-6"><aside class="sidebar"><p class="nav-label"><?= $isAdmin ? 'ADMINISTRATION' : 'STUDENT PORTAL' ?></p><nav><?php foreach ($nav as [$label,$href,$key]): ?><a class="side-link <?= $active===$key?'is-active':'' ?>" href="<?= e(app_url($href)) ?>"><span class="side-dot"></span><?= e($label) ?></a><?php endforeach ?></nav><div class="sidebar-note"><span class="gold-line"></span><p>Learn with purpose.<br><b>Grow with confidence.</b></p></div></aside><main class="min-w-0"><div class="mb-5"><p class="eyebrow"><?= $isAdmin ? 'SCHOOL MANAGEMENT' : 'YOUR LEARNING SPACE' ?></p><h1 class="page-title"><?= e($title) ?></h1></div><?php if ($flash): ?><div class="alert <?= $flash['type']==='error'?'alert-error':'alert-success' ?>"><?= e($flash['message']) ?></div><?php endif ?>
    <?php else: ?><main class="mx-auto min-h-[75vh] max-w-7xl px-4 py-10 lg:px-6"><?php if ($flash): ?><div class="alert <?= $flash['type']==='error'?'alert-error':'alert-success' ?> mb-5"><?= e($flash['message']) ?></div><?php endif ?><?php endif;
}
function end_page(): void { if (current_user()) echo '</main></div>'; else echo '</main>'; ?><footer class="site-footer"><div class="mx-auto flex max-w-7xl flex-col justify-between gap-2 px-5 py-6 sm:flex-row"><span>© <?= date('Y') ?> Warwa International School</span><span>Knowledge • Character • Opportunity</span></div></footer><script src="<?= e(app_url('assets/js/app.js')) ?>"></script></body></html><?php }
